  const PQ = (title, q, answer, params) => P(title, q, answer, { params });
  SET['매개변수 쿼리'] = [
    PQ('학과코드 입력', '[학생]에서 실행할 때 "학과코드를 입력하세요"라고 묻고, 입력한 학과의 이름을 표시하시오. (입력값: C02)', 'SELECT 이름 FROM 학생 WHERE 학과코드 = [학과코드를 입력하세요]', ['C02']),
    PQ('학년 입력', '[학생]에서 [학년 입력]으로 학년을 받아 그 학년 학생의 이름, 학년을 표시하시오. (입력값: 3)', 'SELECT 이름, 학년 FROM 학생 WHERE 학년 = [학년 입력]', [3]),
    PQ('이름 일부 (Like)', '[학생]에서 [이름의 일부 입력]으로 받은 글자가 이름에 들어 있는 학생을 표시하시오. (입력값: 서)', 'SELECT 이름 FROM 학생 WHERE 이름 Like "*" & [이름의 일부 입력] & "*"', ['서']),
    PQ('성 입력 (Like)', '[학생]에서 [성 입력]으로 받은 글자로 시작하는 학생의 이름을 표시하시오. (입력값: 김)', 'SELECT 이름 FROM 학생 WHERE 이름 Like [성 입력] & "*"', ['김']),
    PQ('점수 이상', '[수강]에서 [최저 점수]를 받아 그 점수 이상인 학번, 점수를 표시하시오. (입력값: 85)', 'SELECT 학번, 점수 FROM 수강 WHERE 점수 >= [최저 점수]', [85]),
    PQ('기간 (Between)', '[수강]에서 [시작일]과 [종료일]을 받아 그 사이 수강일의 수강번호, 수강일을 표시하시오. (입력값: 2024-03-05, 2024-03-06)', 'SELECT 수강번호, 수강일 FROM 수강 WHERE 수강일 Between [시작일] And [종료일]', ['2024-03-05', '2024-03-06']),
    PQ('과목명 입력 (조인)', '[수강]과 [과목]을 연결해 [과목명 입력]으로 받은 과목의 학번, 점수를 표시하시오. (입력값: 데이터베이스)', `SELECT 학번, 점수 FROM ${J2} WHERE 과목명 = [과목명 입력]`, ['데이터베이스']),
    PQ('학과명 입력 (조인)', '[학생]과 [학과]를 연결해 [학과명을 입력하세요]로 받은 학과 학생의 이름을 표시하시오. (입력값: 디자인학과)', `SELECT 이름 FROM ${J1} WHERE 학과명 = [학과명을 입력하세요]`, ['디자인학과']),
    PQ('성별 입력', '[학생]에서 [성별 입력]으로 받은 성별 학생의 이름, 성별을 이름 순으로 표시하시오. (입력값: 여)', 'SELECT 이름, 성별 FROM 학생 WHERE 성별 = [성별 입력] ORDER BY 이름', ['여']),
    PQ('출생 연도 입력', '[학생]에서 [출생 연도]로 받은 연도에 태어난 학생의 이름을 표시하시오. (Year, 입력값: 2003)', 'SELECT 이름 FROM 학생 WHERE Year(생년월일) = [출생 연도]', [2003]),
    PQ('장학금 이상', '[학생]에서 [최소 장학금]을 받아 그 이상인 학생의 이름, 장학금을 표시하시오. (입력값: 400000)', 'SELECT 이름, 장학금 FROM 학생 WHERE 장학금 >= [최소 장학금]', [400000]),
    PQ('교수 입력', '[과목]에서 [담당교수 입력]으로 받은 교수의 과목명을 표시하시오. (입력값: 이교수)', 'SELECT 과목명 FROM 과목 WHERE 담당교수 = [담당교수 입력]', ['이교수']),
    PQ('학번 입력', '[수강]에서 [학번을 입력하세요]로 받은 학번의 과목코드, 점수를 표시하시오. (입력값: S003)', 'SELECT 과목코드, 점수 FROM 수강 WHERE 학번 = [학번을 입력하세요]', ['S003']),
    PQ('학년 범위', '[학생]에서 [시작 학년]부터 [끝 학년]까지의 학생 이름, 학년을 표시하시오. (입력값: 2, 3)', 'SELECT 이름, 학년 FROM 학생 WHERE 학년 Between [시작 학년] And [끝 학년]', [2, 3]),
    PQ('구분 입력', '[과목]에서 [구분 입력]으로 받은 구분의 과목명, 학점을 표시하시오. (입력값: 교양)', 'SELECT 과목명, 학점 FROM 과목 WHERE 구분 = [구분 입력]', ['교양']),
    PQ('월 입력', '[학생]에서 [생일 월]로 받은 월에 태어난 학생의 이름을 표시하시오. (Month, 입력값: 2)', 'SELECT 이름 FROM 학생 WHERE Month(생년월일) = [생일 월]', [2]),
    PQ('점수 미만', '[수강]에서 [기준 점수]보다 낮은 학번, 과목코드, 점수를 표시하시오. (입력값: 70)', 'SELECT 학번, 과목코드, 점수 FROM 수강 WHERE 점수 < [기준 점수]', [70]),
    PQ('학과 + 학년', '[학생]에서 [학과코드]와 [학년]을 모두 받아 해당 학생의 이름을 표시하시오. (입력값: C01, 3)', 'SELECT 이름 FROM 학생 WHERE 학과코드 = [학과코드] And 학년 = [학년]', ['C01', 3]),
    PQ('과목명 일부 (조인)', '[수강]과 [과목]을 연결해 과목명에 [단어 입력]이 들어 있는 과목의 과목명, 점수를 표시하시오. (입력값: 디자인)', `SELECT 과목명, 점수 FROM ${J2} WHERE 과목명 Like "*" & [단어 입력] & "*"`, ['디자인']),
    PQ('세 테이블 이름 입력', '세 테이블을 연결해 [학생 이름 입력]으로 받은 학생의 과목명, 점수를 표시하시오. (입력값: 정하늘)', `SELECT 과목명, 점수 FROM ${J3} WHERE 이름 = [학생 이름 입력]`, ['정하늘']),
    PQ('연락처 끝자리', '[학생]에서 연락처가 [끝 4자리]로 끝나는 학생의 이름을 표시하시오. (Like, 입력값: 5678)', 'SELECT 이름 FROM 학생 WHERE 연락처 Like "*" & [끝 4자리]', ['5678']),
    PQ('날짜 이후', '[수강]에서 [기준일] 이후(포함) 수강일의 수강번호를 표시하시오. (입력값: 2024-03-06)', 'SELECT 수강번호 FROM 수강 WHERE 수강일 >= [기준일]', ['2024-03-06']),
    PQ('학점 입력', '[과목]에서 [학점 입력]과 같은 학점의 과목명을 표시하시오. (입력값: 2)', 'SELECT 과목명 FROM 과목 WHERE 학점 = [학점 입력]', [2]),
    PQ('단과대학 입력 (조인)', '[학생]과 [학과]를 연결해 [단과대학 입력]으로 받은 대학 학생의 이름, 학과명을 표시하시오. (입력값: 경영대학)', `SELECT 이름, 학과명 FROM ${J1} WHERE 단과대학 = [단과대학 입력]`, ['경영대학']),
    PQ('입력 + 정렬', '[수강]에서 [과목코드 입력]으로 받은 과목의 학번, 점수를 점수 내림차순으로 표시하시오. (입력값: K02)', 'SELECT 학번, 점수 FROM 수강 WHERE 과목코드 = [과목코드 입력] ORDER BY 점수 DESC', ['K02']),
    PQ('입력 집계', '[수강]에서 [과목코드 입력]으로 받은 과목의 평균 점수를 표시하시오. (입력값: K01)', 'SELECT Avg(점수) AS 평균 FROM 수강 WHERE 과목코드 = [과목코드 입력]', ['K01']),
    PQ('학번 앞부분', '[학생]에서 학번이 [학번 앞부분]으로 시작하는 학생의 학번, 이름을 표시하시오. (입력값: S00)', 'SELECT 학번, 이름 FROM 학생 WHERE 학번 Like [학번 앞부분] & "*"', ['S00']),
    PQ('장학금 범위', '[학생]에서 장학금이 [최소]부터 [최대] 사이인 학생의 이름, 장학금을 표시하시오. (입력값: 100000, 500000)', 'SELECT 이름, 장학금 FROM 학생 WHERE 장학금 Between [최소] And [최대]', [100000, 500000]),
    PQ('학년 이하', '[학생]에서 [최대 학년] 이하인 학생의 이름, 학년을 학년 순서로 표시하시오. (입력값: 2)', 'SELECT 이름, 학년 FROM 학생 WHERE 학년 <= [최대 학년] ORDER BY 학년', [2]),
    PQ('이름 정확히', '[학생]에서 [이름 입력]과 같은 학생의 연락처를 표시하시오. (입력값: 박지호)', 'SELECT 연락처 FROM 학생 WHERE 이름 = [이름 입력]', ['박지호']),
  ];

  // 크로스탭: 행 × 열 × 집계 조합
  const CT = [];
  const ctPairs = [['학과코드', '성별'], ['학과코드', '학년'], ['학년', '성별'], ['성별', '학과코드'], ['학년', '학과코드'], ['성별', '학년']];
  const ctAggs = [['Count(학번)', '인원'], ['Sum(장학금)', '장학금 합계'], ['Avg(장학금)', '평균 장학금'], ['Max(장학금)', '최대 장학금']];
  ctPairs.forEach(([r, c]) => ctAggs.forEach(([a, an]) =>
    CT.push(P(`${r}×${c} ${an}`, `[학생]에서 행 머리글은 ${r}, 열 머리글은 ${c}, 값은 ${an}(${a})인 크로스탭 쿼리를 작성하시오.`,
      `TRANSFORM ${a} SELECT ${r} FROM 학생 GROUP BY ${r} PIVOT ${c}`))));
  CT.push(P('학번×과목 점수', '[수강]에서 행 머리글은 학번, 열 머리글은 과목코드, 값은 점수 합계인 크로스탭 쿼리를 작성하시오.', 'TRANSFORM Sum(점수) SELECT 학번 FROM 수강 GROUP BY 학번 PIVOT 과목코드'));
