  // 설정 문제: [제목, 문제, [[항목, 보기 목록, 정답], …], 작업 순서]
  const Q = (title, q, fields, steps) => ({ title, q, fields: fields.map(([label, options, answer]) => ({ label, options, answer })), steps });
  const FP = ['형식', '입력 마스크', '캡션', '기본값', '유효성 검사 규칙', '유효성 검사 텍스트', '필수', '빈 문자열 허용', '인덱스', '필드 크기', '소수 자릿수', '텍스트 맞춤'];
